### Description

Considering the modular nature of the node material, it would be beneficial to be able to use any uv indexes out of the box as part of these two nodes instead of the hardcoded index 0.

There is also a discrepancy between the input of these two nodes. One is accepting a `TextudeNode` and the other one a `Texture`. I believe both shall use the same type of input, probably a `TextureNode`to be consistent.

### Solution

Here is the code I currently use in my project - 

* BumpMapNode
```js
const dHdxy_fwd = tslFn(({ bumpTexture, uvNode, bumpScale }) => {
  const Hll = texture(bumpTexture.value, uvNode).x;

  return vec2(
    texture(bumpTexture.value, uvNode.add(uvNode.dFdx())).x.sub(Hll),
    texture(bumpTexture.value, uvNode.add(uvNode.dFdy())).x.sub(Hll),
  ).mul(bumpScale);
});

class BumpMapNode extends TempNode {
  constructor(node, uvNode = null, scaleNode = null) {
    super('vec3');

    this.node = node;
    this.uvNode = uvNode || uv();
    this.scaleNode = scaleNode;
  }

  construct() {
    const bumpScale = this.scaleNode !== null ? this.scaleNode : 1;
    const dHdxy = dHdxy_fwd({ bumpTexture: this.node, uvNode: this.uvNode, bumpScale });

    return perturbNormalArb({
      surf_pos: positionView,
      surf_norm: normalView,
      dHdxy,
    });
  }
}
```

* NormalMapNode
```js
class NormalMapNode extends TempNode {
  constructor(node, uvNode = null, scaleNode = null) {
    super('vec3');

    this.node = node;
    this.scaleNode = scaleNode;
    this.uvNode = uvNode || uv();

    this.normalMapType = TangentSpaceNormalMap;
  }

  construct(builder) {

    ...

   if (normalMapType === ObjectSpaceNormalMap) {
      outputNode = modelNormalMatrix.mul(normalMap).normalize();
    } else if (normalMapType === TangentSpaceNormalMap) {
      const tangent = builder.hasGeometryAttribute('tangent');

      if (tangent === true) {
        outputNode = TBNViewMatrix.mul(normalMap).normalize();
      } else {
        outputNode = perturbNormal2Arb({
          eye_pos: positionView,
          surf_norm: normalView,
          mapN: normalMap,
          uv: this.uvNode,
        });
      }
    }

    return outputNode;
  }
}
```


